/**
 * Calcula o número mínimo de sensores exigido pela norma
 * a partir do volume interno declarado do equipamento.
 */
function cfCalcularSensoresMinimos_(volumeLitros, conjugado) {
  const cfg = CFCFG.SENSORES_POR_VOLUME;
  const vol = Number(volumeLitros);

  if (conjugado) {
    return cfg.minSensoresConjugado;
  }

  if (!isFinite(vol) || vol >= cfg.volumeLimiteLitros) {
    return cfg.minSensoresVolumeGrande;
  }

  return cfg.minSensoresVolumePequeno;
}
